def get_stream(self):
    with xmlfile(self.out) as xf:
        with xf.element("worksheet", xmlns=SHEET_MAIN_NS):
            try:
                while True:
                    el = (yield)
                    if el is True:
                        yield xf
                    elif el is None: # et_xmlfile chokes
                        continue
                    else:
                        xf.write(el)
            except GeneratorExit:
                pass

